INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260617_031256_kvy0', 'ly', 'persona_1779647108414', '2026-06-17T00:00:00', NULL, 'office', '🏢 辦公室', 'excited and energetic', '焦香脆片海苔 梅子風味', 'pullback_reveal', '又晴從抽屜拿出一包海苔脆片,撕開包裝,拿起一片放進嘴裡,咬下的瞬間眼睛微微睜大,表情從平淡轉為驚喜,鏡頭特寫她的側臉和手中的脆片。🎭 又晴直視鏡頭自然地說:「欸我跟你說,這個梅子海苔我原本隨手買來當零食,結果現在抽屜裡隨時都要放一包,那個梅子香氣一咬下去整個在嘴裡散開」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg"]', 15, '09:16:00', 'fast', '720p', 'done', 'https://v3b.fal.media/files/b/0a9e901f/zkjsCAxzqBo4y8-qotfws_video.mp4', 1.21, '019ed1d9-eb1a-7280-9eb4-b57cac8d27f6', 257, 'skipped', NULL, NULL, NULL, 0, '{}', '2026-06-16T19:12:56.692Z', '2026-06-16T19:17:18.502Z', 'active', NULL);
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260617_035411_stuu', 'ly', 'persona_1779647108414', '2026-06-17T00:00:00', NULL, 'office', '🏢 辦公室', 'excited and energetic', '焦香脆片海苔 梅子風味', 'pullback_reveal', '又晴坐在辦公椅上,從抽屜拿出一包梅子海苔脆片,撕開後拿起一片放進嘴裡,眉毛微微上揚露出驚喜表情。🎭 又晴直視鏡頭自然地說:「欸我跟你說,下午嘴饞我都吃這個,梅子海苔脆片真的好吃到會上癮,那個焦香味配梅子酸甜,嗯⋯就是會讓你一片接一片停不下來那種」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg"]', 15, '09:16:00', 'fast', '720p', 'done', 'https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/video/019ed204_0bdd_7152_8b87_-3d428c19ba26816c2da710005ddd72bf4f712640.mp4', 2.42, NULL, 309, 'skipped', NULL, NULL, NULL, 0, '{}', '2026-06-16T19:54:11.028Z', '2026-06-16T19:59:24.103Z', 'active', '接片 2 段');
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260617_043315_6bbu', 'ly', 'persona_1779647108414', '2026-06-17T00:00:00', NULL, 'office', '🏢 辦公室', 'tired but content', '焦香脆片海苔 梅子風味', 'pullback_reveal', '又晴突然抬起頭,眼睛發亮,手裡捏著一片海苔脆片,表情是那種發現寶藏的驚喜感,鏡頭從側面慢慢推近她的臉。🎭 又晴直視鏡頭自然地說:「欸我跟你說,本來想找零食,結果這梅子海苔脆片也太好吃了吧!酸酸鹹鹹又帶焦香,你懂嗎?」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg"]', 15, '09:16:00', 'fast', '720p', 'done', 'https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/video/019ed227_c22b_7293_a42d_-ce418bf300dcdfd42a337c1da24c2dddd974998d.mp4', 2.42, NULL, 300, 'done', '欸我跟你說 辦公室下午三點的救贖  本來只是想隨便找個零食墊胃,結果被這片梅子海苔脆片收服了🥹 那種酸酸鹹鹹帶著焦香的味道,你懂嗎?就是會讓人一片接一片停不下來的那種!  老實說我本來對海苔零食沒什麼期待,但這個真的不一樣欸,梅子味道很明顯但不會太死酸,配著咖啡吃剛剛好☕ 現在抽屜固定有一包備著,下午嘴饞的時候拿出來心情都好了~  💾 先收藏起來,上班嘴饞的時候會需要!  #辦公室零食 #海苔脆片 #梅子控 #下午茶時光 #一人零食 #健康零食 #上班族日常 #療癒小物 #質感零食 #台北上班族 #好滋好滋 #辦公室必備 #嘴饞救星', '下午三點,辦公桌前。  隨手抓了片梅子海苔脆片 結果...停不下來了  那種酸鹹交織的焦香 配咖啡剛剛好  嗯...怎麼說呢 就是會讓人默默清空一包的那種  現在抽屜固定備貨中', '欸我跟你說,今天下午差點在辦公室失控  事情是這樣的,本來只是想找個零食墊胃,隨手拿了包梅子海苔脆片。結果第一片咬下去...那個酸酸鹹鹹帶著焦香的味道整個在嘴裡爆開,我當下就愣住了🤭  老實說我本來對海苔零食沒什麼特別期待,市面上那麼多種不都差不多嗎?但這個真的不一樣欸!梅子的酸味很明顯但不會死酸到皺眉,反而跟海苔的鹹香融合得剛剛好,那個焦脆的口感也處理得很好,不會軟趴趴的。  對欸我也是後來才發現,這種海苔脆片配黑咖啡超搭!酸甜鹹三種味道在嘴裡交織,配上咖啡的苦韻,就那種感覺你懂嗎?突然覺得下午茶可以很精緻~  現在我抽屜固定有一包備著,尤其是趕案子壓力大的時候,吃個幾片心情都好了。而且熱量也不會太誇張,比起洋芋片什麼的我自己是比較能接受啦。這個我可以,真心不騙💚  (默默又拿了一片  你們下午嘴饞的時候都吃什麼?有沒有什麼私藏零食可以分享一下~  #辦公室零食 #梅子海苔 #上班族日常', 0.006, '{}', '2026-06-16T20:33:15.718Z', '2026-06-16T20:38:19.933Z', 'active', '接片 2 段');
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260619_034431_7zvc', 'ly', 'persona_1781733044924', '2026-06-19T00:00:00', NULL, 'office', '🏢 辦公室', NULL, '焦香脆片海苔 梅子風味', 'walk_through', '米禾盯著電腦螢幕,手指在滑鼠上懸停,眉頭微皺,另一手撐著下巴。米禾直視鏡頭自然地說:「改第七版了......客戶說光線再柔一點,可是我覺得現在已經......」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg","https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186135_jpg-1sEGx-vs-t9bFagEuuOuIOYUG_JI5aYqb.jpg"]', 15, '09:16:00', 'fast', '720p', 'failed', NULL, 0, NULL, 0, 'skipped', NULL, NULL, NULL, 0, '{}', '2026-06-18T19:44:31.563Z', '2026-06-18T19:50:57.382Z', 'active', '生成失敗：Unexpected status code: 403');
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260619_051200_zr34', 'ly', 'persona_1781733044924', '2026-06-19T00:00:00', NULL, 'office', '🏢 辦公室', NULL, '焦香脆片海苔 梅子風味', 'static', '米禾坐在辦公桌前盯著電腦螢幕修圖,眉頭微皺調整色溫參數,突然停下手邊動作伸手往桌角摸索,抓起一片海苔放進嘴裡,咀嚼時表情從專注轉為微微驚訝。米禾直視鏡頭自然地說:「欸等等......這個梅子的酸度跟海苔的鹹味......層次有出來欸」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg","https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186135_jpg-1sEGx-vs-t9bFagEuuOuIOYUG_JI5aYqb.jpg"]', 15, '09:16:00', 'fast', '720p', 'done', 'https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/video/019edc98_c6da_7b50_9fe3_-d6ec5b9404b24c634998fe5254e6044133829076.mp4', 2.42, NULL, 353, 'done', '修圖修到一半 突然發現桌上這片海苔......  齁我跟你說,梅子的酸跟海苔的鹹 這個層次有出來欸  平常修色溫都要專注到忘記呼吸 但嘴巴咬著這個反而更集中??? 可能是那個酸甜會讓味蕾醒過來  你懂吧,就是那種 不會死鹹也不會太甜的平衡感 脆度也夠,咬下去會有聲音  我現在修圖都順手抓一片 對不對對不對 👀  #辦公室零食 #海苔控 #梅子海苔 #修圖日常 #美食攝影師 #獨居生活 #深夜加班 #零食推薦 #酸甜口味 #辦公桌必備 #台北租屋 #自由工作者 #下午茶時光  #辦公室零食 #海苔控 #梅子海苔 #修圖日常 #美食攝影師 #獨居生活 #深夜加班 #零食推薦 #酸甜口味 #辦公桌必備 #台北租屋 #自由工作者 #下午茶時光', '修圖修到一半 突然發現桌上這片海苔的層次感  梅子的酸 × 海苔的鹹  這個平衡......可以欸   不會死鹹也不會膩 脆度夠 咬下去有聲音   現在修色溫都順手抓一片 味蕾醒了 專注力也回來了   你懂吧', '坐在電腦前盯著螢幕調色溫參數 眉頭皺了大概有十分鐘  手突然不自覺往桌角摸 抓起一片海苔放進嘴裡 原本只是想隨便吃個東西繼續工作  結果......  欸等等 這個梅子的酸度跟海苔的鹹味 層次有出來欸???  齁我跟你說 平常修圖都專注到會忘記呼吸 但嘴巴咬著這片海苔反而更集中 可能是那個酸甜會讓味蕾突然醒過來 然後腦袋也跟著清楚了  你懂吧,就是那種 不會死鹹也不會太甜的平衡感 脆度也夠,咬下去會有聲音 不是那種軟趴趴或太硬的口感  現在修圖都會順手抓一片 桌上永遠放一包 對不對對不對......  梅子風味的海苔你們有試過嗎 還是你們修圖/工作的時候 都吃什麼零食?  你們工作的時候都吃什麼零食?  #辦公室零食 #修圖日常 #美食攝影師的日常', 0.006, '{}', '2026-06-18T21:12:00.933Z', '2026-06-18T21:17:58.237Z', 'active', '接片 2 段');
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260620_221549_9fun', 'ly', 'persona_1779647108414', '2026-06-20T00:00:00', NULL, 'office', '🏢 辦公室', 'excited and energetic', '焦香脆片海苔 梅子風味', 'pullback_reveal', '又晴盯著電腦螢幕,眉頭微皺,右手托腮,左手滑鼠無意識地點來點去。🎭 又晴直視鏡頭自然地說:「下午三點的會議...怎麼感覺時間過得特別慢」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg","https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186135_jpg-1sEGx-vs-t9bFagEuuOuIOYUG_JI5aYqb.jpg"]', 10, '09:16:00', 'fast', '720p', 'failed', NULL, 0, NULL, 0, 'done', '欸我跟你說,下午三點真的是上班族的死亡時刻😮‍💨 眼皮超重但會議還有兩小時...這時候抽屜那包梅子海苔脆片就是我的救贖啦🌸 酸酸甜甜的一咬下去,瞬間清醒!而且是真的海苔不是調味粉,吃完手不會髒髒的(重點)老實說辦公室零食我現在只認這款,好吃又不會有罪惡感💚 你們下午都吃什麼撐過去的?留言救救我ㄉ零食清單🥺  #辦公室零食 #下午茶時光 #海苔控 #梅子風味 #一人食 #台北上班族 #質感生活 #健康零食 #辦公室日常 #上班族必備 #零食推薦 #療癒小物 #WFH', '下午三點是上班族的靈魂出竅時刻  那種眼皮重到用意志力在撐的感覺  還好抽屜有梅子海苔脆片   酸甜一咬 馬上回魂   對欸我也是後來才發現 原來零食可以不用有罪惡感', '下午三點的辦公室,螢幕藍光刺眼,會議通知跳出來,我托著腮看著時鐘心想:怎麼還有兩小時...  欸我跟你說,這種時候如果沒有零食真的會陣亡。以前我都買那種洋芋片餅乾,吃完手油油的要擦半天,而且越吃越膩越想睡。後來發現這款梅子海苔脆片,整個改觀。  就那種...一咬下去酸酸甜甜的清爽感,瞬間把腦袋叫醒的感覺你懂嗎?而且是真的海苔不是調味粉,吃完手是乾淨的(對我這種龜毛仔來說超重要)嗯...怎麼說呢,就是那種可以放心一直吃、不會有罪惡感的零食。  現在我抽屜固定放三包,下午茶、加班、週末在家追劇都靠它。老實說我本來也半信半疑,想說海苔能多好吃?結果現在已經變成回購愛用者了😌  真心不誇張,如果你也是下午會想吃點東西的上班族,這個我可以🌸  你們下午都吃什麼撐過漫長會議?有推薦的零食嗎?  #辦公室零食 #上班族日常 #質感生活', 0.006, '{}', '2026-06-20T14:15:49.790Z', '2026-06-20T14:16:14.811Z', 'active', '[seedance_submit] seedance_submit 失敗: put: Reduce your concurrent request rate for the same object. (10058)');
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260620_231911_v7rv', 'ly', 'persona_1781733044924', '2026-06-20T00:00:00', NULL, 'office', '🏢 辦公室', NULL, '焦香脆片海苔 梅子風味', 'static', '米禾坐在辦公桌前盯著電腦螢幕調色,眉頭微皺,右手不自覺摸肚子。米禾直視鏡頭自然地說:「齁我從早上九點修圖修到現在......肚子已經在抗議了」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg","https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186143_jpg-1cY0QXkWT-LU1MbrMcnMoOeRUJoLj3AtR.jpg"]', 10, '09:16:00', 'fast', '720p', 'done', 'https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/video/019ee5a3_64a9_7372_85e4_-22ba383d3368d7961bc4bdb39a615d66a3c83cc4.mp4', 7.26, NULL, 427, 'done', '齁我從早上九點修圖修到現在......肚子已經在抗議了🥲  欸但認真,修圖修到忘我的時候,抽屜那包梅子海苔脆片真的救命。酸酸甜甜那種,咬下去會ㄎㄠˋㄎㄠˋ脆的質地,香氣有層次欸......先是梅子的酸,後面才是海苔鹹香。  而且不會像一般零食吃完手油油,我可以一邊咬一邊繼續調色溫,你懂吧?  深夜肚子餓但又懶得煮的時候,這個真的可以。先聞聞看啦,那個梅子味會先衝上來💭  👉🏻 儲存這篇給修圖修到忘記吃飯的你  #修圖人生 #深夜零食 #梅子海苔 #辦公室救星 #美食攝影師日常 #獨居料理 #健康零食 #海苔脆片 #酸甜口味 #加班良伴 #台北租屋 #自由接案 #攝影師的日常', '從早上九點修圖修到現在 肚子已經在抗議了   但那包梅子海苔脆片真的救命  酸酸甜甜的 咬下去會ㄎㄠˋㄎㄠˋ脆 不會吃完手油油   可以一邊咬一邊調色溫  你懂吧', '齁我跟你說,自由接案最可怕的不是沒案子,是接了案子之後修圖修到忘我......  今天從早上九點坐到現在,眼睛盯著螢幕調色調到快脫窗,肚子已經在抗議了。本來想說等等修完這張再去煮東西,結果手不自覺伸進抽屜,摸到那包梅子海苔脆片。  欸這個真的可以欸。  咬下去那個ㄎㄠˋㄎㄠˋ脆的質地,先是梅子的酸衝上來,後面才是海苔的鹹香。重點是不會像一般零食吃完手油油的,我可以一邊咬一邊繼續調色溫,對不對對不對!  而且那個香氣有層次......梅子味先出來,海苔香氣後勁才慢慢跟上。這種零食拿來當修圖良伴真的剛好,不會太膩、也不會吃完罪惡感爆棚。  深夜肚子餓但又懶得開火的時候,抽屜常備這個真的救命。先聞聞看啦,那個酸甜味會讓你瞬間清醒......  你修圖或加班的時候都吃什麼?還是你也是那種餓到不行才發現「哇已經九點了」的人?  你修圖或加班的時候都吃什麼?還是你也是那種餓到不行才發現「哇已經九點了」的人?  #修圖日常 #自由接案 #深夜零食', 0.006, '{}', '2026-06-20T15:19:11.636Z', '2026-06-20T15:26:22.524Z', 'active', '接片 6 段');
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260621_021255_hzst', 'ly', 'persona_1781733044924', '2026-06-21T00:00:00', NULL, 'office', '🏢 辦公室', 'warm and gentle', '焦香脆片海苔 梅子風味', 'static', '米禾坐在辦公桌前盯著螢幕修圖,突然停下來揉眼睛,視線飄向桌角一個牛皮紙袋。米禾直視鏡頭自然地說:「修了三小時圖......眼睛要脫窗了」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg","https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186129_jpg-1h01SyBBwTrZYAPzRbzEHVQfphkVoiQ5t.jpg"]', 10, '09:16:00', 'fast', '720p', 'done', 'https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/video/019ee642_91d2_7043_87f7_-19b6ad90b86e7172fa691927fcac4fc52df9be57.mp4', 7.26, NULL, 437, 'done', '修圖修到眼睛要脫窗......  齁我跟你說,這種時候就是要來點酸的醒腦。桌上那包梅子海苔脆片,聞到那個梅子香氣就覺得可以再戰三小時欸。  呢個酸甜比例抓得很剛好,不會死鹹,咬下去是脆的不是軟的(這點很重要對不對)一片接一片停不下來......  你們修圖的時候都吃什麼?留言跟我說啦~  👉🏻 收藏起來下次嘴饞備用  #修圖日常 #美食攝影師 #辦公室零食 #海苔控 #梅子風味 #酸甜滋味 #深夜加班良伴 #零食推薦 #台北租屋生活 #自由接案日常 #工作室日常 #獨居料理', '修圖三小時眼睛要脫窗  突然好想吃酸的    桌上那包梅子海苔脆片救了我    欸你懂吧 有時候就是需要那個酸勁把腦袋拉回來', '修了三小時圖,眼睛真的要脫窗了......  盯著螢幕調色調到懷疑人生的時候,視線突然飄到桌角那個牛皮紙袋。裡面是前幾天在超市看到就順手帶回來的梅子海苔脆片。  齁我跟你說,打開的瞬間那個梅子香氣就竄出來了。不是那種化學酸味,是真的有梅子的層次感欸。咬下去的口感也很可以——是脆的不是軟的(這點對我來說超重要對不對),然後酸甜比例抓得剛剛好,不會死鹹也不會太甜。  一片接一片,配著黑咖啡繼續修圖,突然覺得可以再戰三小時。  呢個真的可以,推薦給所有需要長時間盯螢幕的人。先聞聞看那個香氣啦,你就懂我在說什麼了。  對了,你們修圖或加班的時候都吃什麼零食?有沒有什麼私藏款可以分享一下?  你們修圖或加班的時候都吃什麼零食?有沒有什麼私藏款可以分享一下?  #修圖日常 #美食攝影師的日常 #辦公室零食', 0.006, '{}', '2026-06-20T18:12:55.456Z', '2026-06-20T18:20:16.523Z', 'active', '接片 6 段');
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260621_050450_geuw', 'flm', 'persona_1780903052363', '2026-06-21T00:00:00', NULL, 'flm_chef_craft', '👨‍🍳 主廚手路菜', NULL, '當紅炸子雞', 'static', '阿福在廚房爐火前俐落地炒這道招牌菜,鏡頭一轉,菜已經完成、漂亮裝在白盤裡端上桌,熱氣騰騰,他笑著介紹。', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/flm/product/16_jpg-1s2GC1JXloJThqbEiPDN5RNQH8-Ks0xx8.jpg"]', 10, '09:16:00', 'fast', '720p', 'done', 'https://v3b.fal.media/files/b/0a9f19c3/PdN37YFWL038Yz6_iypxp_video.mp4', 1.21, '019ee6d9-d378-7f22-a0d0-d88897673119', 228, 'done', '🔥 呢味炸子雞  講真,睇師傅炒呢味係一種享受。火候要啱、手勢要快,先做到皮脆肉嫩、色澤金紅咁靚。我同你講,呢啲功夫菜真係要時間熬出嚟嘅,唔係話想整就整到。  啱啱出爐嗰陣,熱氣仲冒緊,夾起一塊咬落去,外脆內軟,肉汁鎖得好實,呢個就係正宗粵菜嘅真功夫啦。👨‍🍳  收藏呢個帖,下次約老友記飯局就知去邊度搵好嘢食 💾  #當紅炸子雞 #粵菜 #香港美食 #米其林 #灣仔美食 #傳統手工 #師傅手藝 #港式美食 #老派做法 #識食 #美食推薦 #HongKongFood #粵菜文化 #炸子雞', '師傅手勢好重要   睇住爐火前嗰雙手 炒得快、收得準 先做到皮脆肉嫩   呢啲功夫菜 真係急唔嚟嘅   食咗咁多年 呢味最記得 🔥', '啱啱去睇師傅炒呢味當紅炸子雞,站喺廚房爐火前面,真係好欣賞佢哋嘅手勢。  火要夠猛、時間要拿捏準,炒得太耐會柴,火候唔夠又唔夠香。我同你講,要做到皮脆肉嫩、色澤金紅咁靚,師傅手勢好重要,呢啲細節位,識食嘅先知。  鏡頭一轉,熱辣辣嘅炸子雞已經擺喺白瓷碟度,熱氣仲冒緊,夾起一塊咬落去,外層脆到起角,但入面個雞肉軟嫩多汁,肉汁鎖得好實,呢個就係老派做法先有嘅老派味道嘛。  講真,呢啲功夫菜真係要時間熬出嚟嘅,唔係話想整就整到。正宗粵菜就係要咁樣做先啱,要食就食師傅真功夫啦。食咗咁多年粵菜,有啲味道係會一直記得嘅。  你哋鍾意食邊款傳統粵菜?有冇啲味道係食過一次就記得成世嘅?  #粵菜 #香港美食 #米其林 #師傅手藝 #傳統工序', 0.006, '{}', '2026-06-20T21:04:50.432Z', '2026-06-20T21:08:46.094Z', 'active', NULL);
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260704_181852_0vlj', 'ra', 'persona_1782803638301', '2026-07-04T00:00:00', NULL, 'sports_outlet', '👟 運動賣場特賣', NULL, '運動鞋Outlet', 'static', '定場遠景:她站在特賣會入口,手裡拎著帆布袋,眼神掃視著擺滿鞋盒的長桌,淺景深讓背後的人潮虛化成光斑 欣怡直視鏡頭自然地說出這一句完整的話,說完立刻停止:「欸我跟你說齁,今天逛到 Champion 的特賣會,正版品牌價格超佛心,只到七月十九號,買一送一整個停不下來」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ra/product/S__66617435_0_jpg-1XE91mV6p0bFdju4Nv433DYO_w6LTIO1U.jpg","https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ra/product/S__66617438_0_jpg-1h7ZtTzqRYf4OcHZAsYyqX9nkxIPLknSU.jpg"]', 15, '09:16:00', 'fast', '720p', 'planned', NULL, 0, NULL, 0, 'pending', NULL, NULL, NULL, 0, '{}', '2026-07-04T10:18:52.587Z', '2026-07-04T10:18:52.587Z', 'active', NULL);
